import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as r,c as s,a as t,b as e,e as d,d as i}from"./app-ca2b8cb3.js";const l={},c=i('<h1 id="pre-registration-draft-—-ef-vs-if-attentional-encoding-in-imu-driven-ar-mediated-fpa-retraining" tabindex="-1"><a class="header-anchor" href="#pre-registration-draft-—-ef-vs-if-attentional-encoding-in-imu-driven-ar-mediated-fpa-retraining" aria-hidden="true">#</a> Pre-Registration Draft — EF vs IF Attentional Encoding in IMU-Driven AR-Mediated FPA Retraining</h1><p><strong>Status</strong>: Draft, for researcher review before formal submission to OSF Registries (Standard Pre-Data Collection Registration template).<br><strong>Source</strong>: Content compiled from <code>01_Protocol/Protocol_Master_Draft.md</code> (finalized version, incorporating all researcher decisions).<br><strong>Venue track</strong>: This preregistration is intended for a <strong>Registered Report</strong> submission (Stage 1: in-principle review of the question, design, and analysis plan prior to data collection, followed by Stage 2 result-neutral publication commitment after data collection — see Section 1 for the explicit publish-regardless-of-outcome commitment). Target journal: <strong>Sensors (MDPI)</strong> is the current default candidate given the sensor-hardware-forward framing, but the venue is <strong>not locked</strong> — a Registered-Report-track journal offering a better fit (e.g. higher standing in Sport Sciences/Rehabilitation Engineering, see the earlier CAS-tier discussion) will be considered before Stage 1 submission, provided it accepts Registered Reports in this subject area.<br><strong>Must be completed before submission</strong>: Researcher reads through the full text to confirm accuracy → copy/adapt into the official OSF form (and/or the chosen journal&#39;s Registered Report Stage 1 template, once the venue is finalized) → submit and lock (cannot be edited after submission; any subsequent change requires an OSF amendment with a timestamped record).<br><strong>Revision note (post-frontend-update sync)</strong>: This draft has been updated to reflect the Unity AR client as currently implemented (<code>IMUMoCap/docs/summry/AR-FRONTEND.md</code>), which has diverged from the design frozen in <code>Protocol_Master_Draft.md</code> Section 4.1 in several respects (icon rendering, on-screen dwell time, feedback colour valence, focus-reminder duration — see Section 6 &quot;Newly reintroduced asymmetries&quot; and Section 7 Limitations). This introduces two newly identified confounds (unequal target-icon dwell time; unequal feedback-valence coding between EF and IF) in addition to the confounds already discussed in the prior review round.</p><p><strong>Confound-resolution decision (recorded)</strong>: Per the Round 3 preregistration-review panel&#39;s Must-Fix #1 (<code>Preregistration_Review_Report_Round3.md</code>), the authors have resolved the previously-open accept-vs-fix fork in Section 6 by selecting <strong>Option (b)</strong>: a further AR-frontend revision was requested and has been completed. The implementation described throughout Sections 5-7 (EF: stone target visible continuously for the block, pulsed scale/colour, orange-only &quot;missed&quot; signal; IF: footprint hidden by default, flashing briefly on each foot-contact event with bidirectional blue/orange colour) is the <strong>confirmed, final build for data collection</strong> — it is not a placeholder pending a further engineering decision. The two confounds disclosed below (dwell-time asymmetry, feedback-valence asymmetry) are <strong>not eliminated by this revision</strong>; they are present in this final build and are retained as deliberately-accepted, disclosed limitations of the chosen EF/IF operationalization, per the directional-bias analysis added to Section 6. <code>Protocol_Master_Draft.md</code> Section 4.1 still needs a mechanical re-sync to match this confirmed build before the Stage 1 freeze timestamp is set (see Companion document freeze policy, Section 6) — that resync is now a bookkeeping task, not an open design decision.</p><hr><h2 id="_1-study-information" tabindex="-1"><a class="header-anchor" href="#_1-study-information" aria-hidden="true">#</a> 1. Study Information</h2><p><strong>Title</strong>: EF vs. IF Attentional Encoding in IMU-Driven AR-Mediated FPA Retraining: A Parallel Comparison of Behavioral and Candidate Mechanism-Adjacent Indicators</p><p><strong>Authors</strong>: Xiasong Chen, Niall Murray, Thiago Braga Rodrigues (author order consistent with the published IMX&#39;26 paper)</p><p><strong>Description / Background</strong>:<br> Foot progression angle (FPA) is a modifiable gait parameter relevant to knee osteoarthritis (KOA) and knee adduction moment (KAM) (Guo, Axe, &amp; Manal, 2007, <em>Gait &amp; Posture</em>, 26(3), 436–441, DOI: 10.1016/j.gaitpost.2006.10.008). Prior AR/IMU-based FPA feedback systems (e.g. Karatsidis, Richards, Konrath, van den Noort, Schepers, Bellusci, Harlaar, &amp; Veltink, 2018, <em>Journal of NeuroEngineering and Rehabilitation</em>, 15:78, DOI: 10.1186/s12984-018-0419-2) default to internal-focus (IF) style feedback without this design choice having been examined against external-focus (EF) alternatives. This study extends a previously published baseline-driven personalized FPA retraining system (Chen, Murray &amp; Rodrigues, 2026, ACM IMX&#39;26, DOI: 10.1145/3788851.3812844) to directly compare EF vs IF attentional encoding, reframing the research question from a Quality-of-Experience (QoE) evaluation to a <strong>parallel comparison of behavioral and candidate mechanism-adjacent indicators</strong> associated with two theoretically-grounded pathways proposed to underlie any external-focus advantage (this is <strong>not</strong> a formal mediation/path analysis — see Section 6 for the confirmatory group comparisons and the exploratory indirect-effect estimate reported alongside them):</p><ol><li>The constrained-action hypothesis (EF → reduced conscious motor control → reduced cognitive load; Wulf, McNevin, &amp; Shea, 2001, <em>The Quarterly Journal of Experimental Psychology Section A</em>, 54(4), 1143–1154, DOI: 10.1080/713756012; reviewed in Wulf, 2013, <em>International Review of Sport and Exercise Psychology</em>, 6(1), 77–104, DOI: 10.1080/1750984X.2012.723728)</li><li>OPTIMAL theory&#39;s enhanced-expectancies pathway (EF → strengthened goal-action coupling → increased perceived competence; Wulf &amp; Lewthwaite, 2016, <em>Psychonomic Bulletin &amp; Review</em>, 23(5), 1382–1414, DOI: 10.3758/s13423-015-0999-9)</li></ol><p>This study manipulates one of OPTIMAL theory&#39;s three proposed factors (external focus of attention) and measures a candidate indicator of the mechanism it is theoretically predicted to engage (enhanced expectancies, via IMI Perceived Competence); OPTIMAL&#39;s third factor (autonomy support) is held constant across conditions and is explicitly <strong>not tested</strong>, due to sample size constraints (a full factorial test of all three factors would require a design well beyond what N=22 supports).</p><p><strong>Literature gap verification</strong>: An independent literature check (PubMed, Crossref, Google Scholar; see <code>00_Background/Literature_Check_Report.md</code>) confirmed no published study has directly compared EF vs IF attentional encoding within an AR/IMU gait retraining system targeting FPA specifically.</p><p><strong>Publication commitment</strong>: Consistent with this study&#39;s anti-p-hacking design philosophy (see Section 6&#39;s multiple-comparisons policy and its commitment to reporting exact p-values, effect sizes, and confidence intervals for all primary comparisons regardless of significance), the authors commit to submitting the results for publication <strong>regardless of the direction or statistical significance of the outcomes</strong>, including null or mixed results across the six primary hypotheses.</p><p><strong>Translational context</strong>: This study isolates candidate attentional-focus mechanisms in a healthy, AR-naive population using a controlled AR/IMU protocol; it is explicitly a <strong>mechanism-isolation study, not a clinical efficacy trial</strong>. However, by establishing whether EF or IF encoding yields superior FPA target achievement, retention, and lower cognitive load, this work is intended to directly inform the feedback-encoding design choices of the next-stage AR/IMU gait-retraining systems aimed at knee osteoarthritis (KOA) populations, for whom toe-in/toe-out FPA modification is an established, non-pharmacological intervention for reducing knee adduction moment and pain (Guo, Axe, &amp; Manal, 2007). Identifying an evidence-based default attentional-focus encoding at this healthy-adult proof-of-mechanism stage is intended to de-risk the feedback design of a future clinical (KOA) trial, rather than requiring that later trial to separately test EF vs IF from scratch.</p><p><strong>Task-novelty and skill-level caveat</strong>: All participants are AR-naive (prior professional AR/VR experience is an exclusion criterion, Section 4), and the sample is exclusively healthy adults. Attentional-focus effects are known in the broader motor-learning literature to be moderated by task complexity and performer skill level (Wulf, 2013); the magnitude and direction of any EF/IF difference observed here should therefore not be assumed to generalize to AR-experienced users, to more/less complex gait-retraining tasks, or to clinical (e.g. KOA) populations without further study.</p><hr><h2 id="_2-hypotheses" tabindex="-1"><a class="header-anchor" href="#_2-hypotheses" aria-hidden="true">#</a> 2. Hypotheses</h2><blockquote><p>The full rationale for test directionality and the multiple-comparisons strategy is given in <code>01_Protocol/Protocol_Master_Draft.md</code> Section 7.0; only the final version needed for the preregistration is listed here.</p></blockquote><p><strong>RQ1 (Secondary)</strong>: Can a personalized baseline-driven AR feedback system induce measurable FPA changes toward individualized targets in healthy participants?</p><ul><li><strong>H1</strong> (two-tailed, non-directional test of a directional target, see note): Mean FPA during the training block will shift <strong>toward the individualized target direction</strong> (μᵢ ± k·SDᵢ; toe-out training → positive shift, toe-in training → negative shift) relative to baseline FPA (one-sample test against zero shift, per condition). Note: analyzed via two-tailed test against zero (consistent with H1&#39;s non-directional status re: EF vs IF), but interpreted with reference to the pre-specified target direction — a significant shift in the direction <em>opposite</em> the individualized target does <strong>not</strong> count as support for H1, even if statistically significant against zero.</li></ul><p><strong>RQ2 (Primary)</strong>: Do external-focus encoding (EF) and internal-focus encoding (IF) differ in FPA target achievement rate, within-session adaptation trend, and immediate retention effect?</p><ul><li><strong>H2a</strong> (one-tailed, directional): EF will yield a <strong>higher</strong> FPA target achievement rate than IF during the training block.</li><li><strong>H2b</strong> (one-tailed, directional): EF will produce a <strong>smaller</strong> immediate retention decrement than IF (i.e., better retention). <strong>Scoping note</strong>: &quot;retention&quot; here refers strictly to the ~5-minute within-session retention test (feedback removed, following the NASA-TLX(1)+IMI-PC questionnaire delay — see Section 3 Session structure), not longer-term (day/week-scale) motor retention; no claim of longer-term retention is made or tested.</li><li><strong>H2c</strong> (two-tailed, non-directional): EF and IF will show different condition × block interaction patterns in within-session FPA adaptation trend.</li></ul><p><strong>RQ3 (Primary, revised — parallel comparison)</strong>: Do EF and IF differ on candidate cognitive/motivational indicators associated with the external-focus advantage — namely (i) cognitive load, as a candidate indicator of the constrained-action pathway (H3a), and (ii) perceived competence, as a candidate indicator of the OPTIMAL enhanced-expectancies pathway (H3b) — and are these mechanism-adjacent indicators associated with behavioral FPA outcomes (exploratory)? <strong>Scope note</strong>: this tests one of OPTIMAL theory&#39;s three proposed factors (external focus of attention); the theory&#39;s other two factors (autonomy support, and the intrinsic-motivation pathway more broadly) are not manipulated or tested here (see Section 1).</p><ul><li><strong>H3a</strong> (one-tailed, directional): EF will produce <strong>lower</strong> NASA-TLX cognitive load scores than IF during the feedback-guided training block (Administration 1).</li><li><strong>H3b</strong> (one-tailed, directional): EF will produce <strong>higher</strong> IMI Perceived Competence scores than IF.</li></ul><p><strong>H3c</strong>: Formally withdrawn (originally depended on the Custom QoE questionnaire, which has been removed from the study in its entirety; see Section 5 below and <code>CHANGELOG.md</code> items 1–3, 13 for full history).</p><p><strong>Exploratory analyses (no H-numbers, not error-corrected, not hypothesis-tested in the confirmatory sense)</strong>:</p><ul><li>NASA-TLX (Administration 1) correlation with FPA target achievement rate (Spearman + supplementary LME) — required to fulfil RQ3(revised)&#39;s commitment to testing whether mechanism-adjacent indicators associate with behavioral outcomes</li><li>IMI Perceived Competence correlation with FPA target achievement rate (Spearman + supplementary LME) — added to match RQ3(revised)&#39;s reference to &quot;these mechanism-adjacent indicators&quot; (plural); same rationale as above</li><li>NASA-TLX Administration 2 (feedback removed) vs. Administration 1 (feedback present) descriptive comparison — uses data already collected for confirmatory H3a, no added burden</li><li>Manipulation Check item 3 (stability self-rating) descriptive analysis and optional correlation with NASA-TLX/FPA achievement — tied to the pre-approved extension of the Manipulation Check instrument (Option A, see <code>Protocol_Master_Draft.md</code> Section 5.3)</li></ul><blockquote><p><strong>Note on Order × condition interaction (counterbalance check)</strong>: This is <strong>not</strong> an exploratory hypothesis and has been moved out of this list. It is a precondition/assumption check (verifying the counterbalancing worked as intended before interpreting the primary EF/IF comparisons), listed separately in <code>Protocol_Master_Draft.md</code> Section 7 as a &quot;precondition check (not a numbered hypothesis)&quot;. Standard practice in any crossover design, not a discretionary analysis choice.</p></blockquote><p><strong>Why these 4 items are retained rather than arbitrarily trimmed</strong>: each corresponds to a specific rationale already decided during protocol development (RQ3 consistency ×2, zero-cost reuse of already-collected data, an approved instrument extension) — these are not &quot;ad hoc exploratory additions tacked on after data collection&quot;; the number of items alone does not constitute a rigor problem (see the methodological rationale below), so they are retained.</p><p><strong>Methodological rationale (justification for preregistering exploratory analyses)</strong>:</p><ul><li>Simmons, Nelson, &amp; Simonsohn (2011). False-positive psychology: Undisclosed flexibility in data collection and analysis allows presenting anything as significant. <em>Psychological Science</em>. DOI: 10.1177/0956797611417632</li><li>Wagenmakers, Wetzels, Borsboom, van der Maas, &amp; Kievit (2012). An agenda for purely confirmatory research. <em>Perspectives on Psychological Science</em>. DOI: 10.1177/1745691612463078</li><li>Gelman, A., &amp; Loken, E. (2014). The statistical crisis in science. <em>American Scientist</em>. DOI: 10.1511/2014.111.460</li><li>Nosek, Ebersole, DeHaven, &amp; Mellor (2018). The preregistration revolution. <em>PNAS</em>. DOI: 10.1073/pnas.1708274114</li><li>Wicherts, Veldkamp, Augusteijn, Bakker, van Aert, &amp; van Assen (2016). Degrees of freedom in planning, running, analyzing, and reporting psychological studies: A checklist to avoid p-hacking. <em>Frontiers in Psychology</em>. DOI: 10.3389/fpsyg.2016.01832</li></ul><hr><h2 id="_3-design-plan" tabindex="-1"><a class="header-anchor" href="#_3-design-plan" aria-hidden="true">#</a> 3. Design Plan</h2><p><strong>Study type</strong>: Experiment (within-subjects crossover)</p><p><strong>Blinding</strong>: Participants cannot be blinded to condition (EF vs IF instructions and AR content necessarily differ). Outcome assessors for the FPA/IMU pipeline are automated (no manual scoring), reducing assessor bias for behavioral outcomes. Manipulation Check open-text coding will use two independent raters (see Section 6).</p><p><strong>Study design</strong>: Two-visit within-subjects crossover, EF and IF conditions completed on separate days, <strong>48–72 hours apart</strong> (one condition per day). This interval is a conservative buffer built on top of the ~24h sleep-dependent motor memory consolidation window documented in Walker &amp; Stickgold (2004, DOI: 10.1016/j.neuron.2004.08.031) and Robertson (2004, DOI: 10.1016/j.cub.2004.11.048) — <strong>note</strong>: the literature supports the ≥24h principle, not the specific 48–72h figure itself, which is a practical/scheduling choice; see <code>Protocol_Master_Draft.md</code> Section 8 for the full, transparent caveat.</p><p><strong>Randomization / Counterbalancing</strong>: Participants randomly assigned to one of two order groups (EF-first vs IF-first) to control for practice/order effects. Order × condition interaction checked as a precondition (Mixed ANOVA). Given that this interaction test is itself likely underpowered at N=22 to detect a true order effect (interaction effects typically require substantially larger samples than main effects), <strong>all six primary comparisons (H1–H3b) will be reported in two versions regardless of the precondition result: with and without order as a covariate.</strong> The precondition test result and both versions of each primary comparison will be reported; the precondition result will inform interpretation but will not be used as a binary gate for whether order is considered in the primary analyses.</p><p><strong>Session structure</strong> (per visit, ≈43 min total, see <code>Protocol_Master_Draft.md</code> Section 6.4 for the full stage-by-stage breakdown with measured/estimated time annotations):<br> Pre-session (15 min) → Baseline Walk (100 steps) → Target Generation (&lt;1 min) → Training Block 1 (100 steps/foot) → Rest + Manipulation Check 1 → Training Block 2 (100 steps/foot, no rest/MC after) → Training Block 3 (100 steps/foot) → Rest + Manipulation Check 2 → NASA-TLX Administration 1 + IMI-PC (~5 min, doubles as retention delay) → Retention Test (100 steps, feedback removed) → NASA-TLX Administration 2 (~3 min).</p><hr><h2 id="_4-sampling-plan" tabindex="-1"><a class="header-anchor" href="#_4-sampling-plan" aria-hidden="true">#</a> 4. Sampling Plan</h2><p><strong>Existing data</strong>: None (prospective data collection).</p><p><strong>Inclusion criteria</strong>: Healthy adults, aged 18–65 years; able to walk independently ≥20 minutes without assistive devices; normal or corrected-to-normal vision; no history of lower-limb orthopaedic surgery or acute lower-limb injury.</p><p><strong>Exclusion criteria</strong>: Known gait disorder, neurological condition, or vestibular dysfunction; history of motion sickness/cybersickness; lower-limb pain in the past 6 months affecting walking; prior professional AR/VR training or research experience (controls device-familiarity bias); self-reported colour vision deficiency (e.g., red-green colour blindness), screened via an added item on the Participant Health and Fitness Screening Questionnaire — added because the AR feedback&#39;s deviation signal is colour-coded (see Section 3 and <code>01_Protocol/CHANGELOG.md</code> for the blue/orange palette adopted to reduce this risk further).</p><p><strong>Sample size rationale</strong>: A priori power analysis (G*Power, paired t-test, two-tailed, α=.05, power=.80) using the EF vs IF retention effect size from Chua et al. (2021) meta-analysis (Hedges&#39; g = 0.583, DOI: 10.1037/bul0000335) gives required N=22; <strong>this full calculated N is targeted</strong> (revised upward from an earlier N=18–20 compromise, so recruitment is not stopped below the study&#39;s own calculated requirement). To buffer against anticipated attrition, enrollment will continue slightly beyond 22 as needed to reach <strong>N=22 valid completers</strong> (both sessions). <strong>This study is explicitly framed as an exploratory/pilot investigation</strong>; post-hoc statistical power will be reported for all primary comparisons. Note: switching to one-tailed tests (Section 2) for directional hypotheses makes this power estimate conservative for H2a/H2b/H3a/H3b (achieved power ≈0.84 at N=22 for an effect of this magnitude); for the two-tailed hypotheses (H1, H2c), achieved power at N=22 is ≈0.74 for an effect of this magnitude, and lower still if the true effect is smaller than the borrowed retention effect size. <strong>This a priori power calculation is anchored specifically to H2b&#39;s effect size; a priori power for H1, H2a, H2c, H3a, H3b is not independently established, and effect sizes with confidence intervals — not power/significance claims — will remain the primary basis for interpreting those five hypotheses.</strong></p><p><strong>Borrowed effect-size transferability caveat</strong>: the Chua et al. (2021) meta-analytic effect size (g=0.583) predominantly reflects studies using distal/classic external-focus instructions (e.g., verbal cues directing attention to an external object or effect); its applicability to this study&#39;s <strong>proximal EF operationalization</strong> (a head-locked, 3DoF AR display, see Section 3 and Protocol_Master_Draft.md Section 8 Limitations) has not been independently established and may overestimate the achievable effect. As a sensitivity check, achieved power at N=22 for smaller, plausible effect sizes is: d=0.5 → 61% (two-tailed) / 73% (one-tailed); d=0.4 → 43% / 57%; d=0.3 → 27% / 39%. Readers should treat the power estimate above as an optimistic upper bound rather than a guarantee, particularly for H1 and H2c.</p><p><strong>Stopping rule</strong>: Data collection stops once N=22 valid participants (completing both sessions) is reached, or at the end of the funded/allotted recruitment window, whichever comes first. Safety stopping rule (per-participant): session discontinued immediately if participant reports &quot;Moderate&quot; or &quot;Severe&quot; on session-level discomfort screening, or requests to stop.</p><p><strong>Missing data / attrition handling policy</strong> (added in response to preregistration review, <code>Preregistration_Review_Report.md</code> Methodology-W4):</p><ul><li><strong>Definition of &quot;valid participant&quot;</strong>: a participant is counted toward N=22 only if they complete the core procedure (baseline walk, all 3 training blocks, retention test) in <strong>both</strong> the EF and IF visits. Completing only one of the two visits does <strong>not</strong> count as a valid participant.</li><li><strong>Participant-level missingness (one visit completed, the other not)</strong>: such participants are excluded from all confirmatory comparisons (H1–H3b), which all require within-person paired data across both conditions. Recruitment continues until N=22 valid participants is reached (per the Stopping rule above), i.e., these participants are effectively replaced, not counted toward the target. Their single-visit data are not discarded from the record: attrition count and stated reason (where available) will be reported descriptively in the eventual manuscript (e.g., a simple enrolled → completed-visit-1 → completed-both-visits flow), and single-visit safety/discomfort data still contribute to the safety-monitoring summary.</li><li><strong>Measurement-level missingness within a completed pair of visits</strong> (both visits completed, but some specific data point is missing or corrupted): <ul><li><em>FPA/step-based outcomes</em>: if a training block or the retention test has a partial step count due to sensor dropout or session interruption, the block&#39;s data are still used <strong>if at least 70% of the intended steps for that block were validly captured</strong>; below that threshold, that specific block is treated as missing for that participant for that outcome only (it does not remove the participant from other blocks/hypotheses).</li><li><em>Single-item rating scales (NASA-TLX&#39;s six subscales, each a standalone 0–100 slider)</em>: a skipped subscale cannot be imputed (there is no sub-item to average) and is treated as missing for that participant on that subscale only; H3a&#39;s per-subscale comparison for that subscale is computed on the remaining valid participants for that subscale.</li><li><em>Multi-item scales (IMI-PC, 5 items)</em>: if exactly 1 of 5 items is missing, the scale score is computed as the mean of the remaining 4 items (standard psychometric practice for short scales); if 2 or more items are missing, the IMI-PC score for that participant/visit is treated as missing.</li></ul></li><li><strong>Reporting commitment</strong>: because the above rules can make the analyzed N differ slightly across H1–H3b, the eventual results will report the <strong>exact analyzed N for each of the six hypotheses individually</strong>, rather than assuming N=22 applies uniformly to every test.</li><li><strong>No imputation is used for participant-level (whole-visit) missingness or for FPA/step-based outcomes beyond the 70% threshold rule above</strong>; this pilot study does not employ multiple imputation, which is judged to add unnecessary researcher degrees of freedom relative to its benefit at this sample size.</li></ul><hr><h2 id="_5-variables" tabindex="-1"><a class="header-anchor" href="#_5-variables" aria-hidden="true">#</a> 5. Variables</h2><p><strong>Manipulated variable</strong>: Attentional focus encoding of AR feedback (EF vs IF), operationalized via AR display content + verbal instruction. As-built AR display behaviour is documented in <code>IMUMoCap/docs/summry/AR-FRONTEND.md</code>; this is the <strong>confirmed final build for data collection</strong> following the Round 3 review&#39;s required confound-resolution decision (Option (b): a further frontend revision was requested and completed — see Section 6 for the decision record and directional-bias analysis). <code>Protocol_Master_Draft.md</code> Section 4.1 still describes an earlier design and is pending a mechanical re-sync to this confirmed build (see Section 6, Companion document freeze).</p><p><strong>Measured variables (confirmatory)</strong>:</p><ul><li>FPA (foot progression angle), estimated in real time via 3× Xsens MTw Awinda IMUs (both feet + pelvis, 100 Hz)</li><li>FPA Absolute Shift, FPA Target Achievement Rate, Within-Session Adaptation Trend, Retention Decrement (all derived from the FPA time series; exact formulas in <code>Protocol_Master_Draft.md</code> Section 3.2)</li><li>NASA-TLX (Raw, 6 subscales), Administration 1 and 2. <strong>Proxy-choice caveat</strong>: NASA-TLX is a self-report subjective workload scale, used here as a <strong>pragmatic, indirect proxy</strong> for the constrained-action hypothesis&#39;s proposed mechanism (&quot;reduced conscious motor control&quot;); it does not directly measure motor automaticity, and more standard direct indicators in that literature (e.g., behavioral dual-task costs, implicit automaticity measures) are not included in this pilot&#39;s battery. This is a deliberate scope/burden trade-off for this exploratory pilot, not an oversight, and readers should interpret H3a accordingly.</li><li>IMI Perceived Competence (5 items: IMI Task Evaluation Questionnaire items 4/7/12/16/22, Markland &amp; Hardy 1997 operationalization, DOI: 10.1080/02701367.1997.10608863)</li></ul><p><strong>Measured variables (non-confirmatory / exploratory / procedural)</strong>:</p><ul><li>Manipulation Check (open response + forced choice + stability self-rating; adapted from Porter, Nolan, Ostrowski &amp; Wulf 2010, DOI: 10.3389/fpsyg.2010.00216, with the stability self-rating item as a study-specific addition beyond the original method — see <code>Protocol_Master_Draft.md</code> Section 5.3)</li><li>Device discomfort / safety screening (verbal, pre-session and each session; pilot-based protocol, n=3 informal, ethics-approved under 008-11-2025, <strong>pilot completed</strong>)</li></ul>',54),h={href:"http://CHANGELOG.md",target:"_blank",rel:"noopener noreferrer"},p=i('<hr><h2 id="_6-analysis-plan" tabindex="-1"><a class="header-anchor" href="#_6-analysis-plan" aria-hidden="true">#</a> 6. Analysis Plan</h2><p><strong>Statistical software</strong>: R (version 4.4.2 or later; exact version and package versions to be confirmed and locked at the time of the analysis script being finalized, e.g. via <code>sessionInfo()</code> / <code>renv::snapshot()</code>). Key packages: <code>stats</code> (base R; Wilcoxon signed-rank tests, paired t-tests, Shapiro-Wilk normality checks), <code>afex</code>/<code>ez</code> (repeated-measures ANOVA, condition × block interaction, H2c), <code>lme4</code> + <code>lmerTest</code> (exploratory linear mixed-effects models), <code>irr</code> (Cohen&#39;s kappa, manipulation check inter-rater agreement), <code>effectsize</code> (standardized effect sizes: Hedges&#39; g, rank-biserial r).</p><table><thead><tr><th>Hypothesis</th><th>Test</th><th>Tails</th><th>Correction</th><th>Outcome classification rule</th></tr></thead><tbody><tr><td>H1</td><td>One-sample Wilcoxon signed-rank (or paired t-test if normality holds, Shapiro-Wilk) vs. zero</td><td>Two-tailed</td><td>None across hypotheses (see below)</td><td><strong>Three-way rule (explicit)</strong>: (a) significant + shift toward the individualized target direction → counts as support for H1; (b) significant + shift in the direction <em>opposite</em> the individualized target → does <strong>not</strong> count as support for H1, even though statistically significant against zero; (c) non-significant → no support for H1. (Full rationale in Section 2.)</td></tr><tr><td>H2a</td><td>Wilcoxon signed-rank (EF vs IF)</td><td>One-tailed (EF &gt; IF)</td><td>None across hypotheses</td><td>Standard directional test; significant + predicted direction = support, otherwise no support</td></tr><tr><td>H2b</td><td>Paired t-test (EF vs IF retention decrement)</td><td>One-tailed (EF &lt; IF decrement)</td><td>None across hypotheses</td><td>Standard directional test; significant + predicted direction = support, otherwise no support</td></tr><tr><td>H2c</td><td>Repeated-measures ANOVA (2 condition × 3 block), condition×block interaction</td><td>Two-tailed</td><td>Greenhouse-Geisser if Mauchly significant; none across hypotheses</td><td>Standard non-directional test; significant interaction (any pattern) = support, otherwise no support</td></tr><tr><td>H3a</td><td>Wilcoxon signed-rank (EF vs IF), per NASA-TLX subscale</td><td>One-tailed (EF &lt; IF)</td><td>Bonferroni <strong>within</strong> the 6 NASA-TLX subscales (local correction only)</td><td>Standard directional test; significant + predicted direction = support, otherwise no support</td></tr><tr><td>H3b</td><td>Wilcoxon signed-rank (EF vs IF), IMI-PC</td><td>One-tailed (EF &gt; IF)</td><td>None across hypotheses</td><td>Standard directional test; significant + predicted direction = support, otherwise no support</td></tr></tbody></table><p><strong>Multiple comparisons policy (must be stated explicitly, decided prior to data collection)</strong>: <strong>No correction is applied across the six primary hypotheses (H1, H2a, H2b, H2c, H3a, H3b).</strong> Rationale: each hypothesis addresses a distinct scientific question (not repeated measurement of the same construct), and this study is explicitly exploratory/pilot (N=22); an overall correction (e.g., Bonferroni to α≈.0083) would substantially reduce already-limited power. As a transparency safeguard, <strong>exact p-values, effect sizes, and confidence intervals will be reported for all primary comparisons</strong> (not binary significant/non-significant labels only), allowing readers to apply their own correction if desired. This decision does not affect the existing <strong>local</strong> Bonferroni correction already applied within the 6 NASA-TLX subscales (a genuinely repeated-construct family). <strong>Per the missing-data policy in Section 4, the exact analyzed N for each of the six hypotheses will also be reported alongside its p-value, effect size, and confidence interval</strong>, since the missing-data rules can make analyzed N differ slightly across H1–H3b rather than uniformly equal to 22.</p><p><strong>Family-wise false-positive rate (quantified)</strong>: under a global null (i.e., if all six hypotheses were truly false), the probability of at least one spurious p&lt;.05 result across the six uncorrected primary comparisons is 1-(1-.05)^6 ≈ <strong>26.5%</strong>. This is explicitly acknowledged rather than left implicit; the authors commit to giving <strong>equal narrative prominence to all six results in the eventual manuscript regardless of which one(s) cross the significance threshold</strong>, so this elevated false-positive risk cannot be selectively exploited by only foregrounding whichever hypothesis happens to reach p&lt;.05.</p><p><strong>Clarification of the &quot;Primary&quot; label</strong>: throughout this document, &quot;Primary&quot; denotes a hypothesis&#39;s <strong>confirmatory-test status</strong> (i.e., it is analyzed with a pre-specified, non-exploratory test and is not subject to post-hoc reinterpretation) — it does <strong>not</strong> denote or imply that the hypothesis is adequately powered. As detailed in Section 4, only H2b has an independent a priori power justification; the other five Primary hypotheses (H1, H2a, H2c, H3a, H3b) are confirmatory in status but of unestablished a priori power.</p><p><strong>Companion document freeze</strong>: the exact outcome-variable formulas (FPA Absolute Shift, FPA Target Achievement Rate, Within-Session Adaptation Trend, Retention Decrement) are defined in <code>Protocol_Master_Draft.md</code> Section 3.2, referenced rather than reproduced here. <strong><code>Protocol_Master_Draft.md</code> is frozen at the same timestamp as this OSF submission</strong>; any subsequent change to Section 3.2&#39;s formulas after submission is treated as a deviation from the pre-registered plan under the same disclosure rule stated in Section 7 (&quot;Deviations from this pre-registration&quot;), not as a silent update to a &quot;living&quot; companion document.</p><p><strong>Manipulation Check analysis</strong>: Pass/failure rate + inter-rater agreement (Cohen&#39;s κ, two independent coders classifying open-text responses) + sensitivity analysis restricted to &quot;passers.&quot; Not hypothesis-tested (no significance test / no H-number).</p><p><strong>Exploratory analyses</strong> (see Section 2 for the list; all Spearman correlations + supplementary linear mixed-effects models): reported descriptively, explicitly flagged as underpowered given N=22 for detecting small-to-medium correlations, no confirmatory claims will be drawn from these. <strong>Additionally</strong>, an exploratory indirect-effect estimate (a×b, using the paired-difference approach appropriate to this two-condition within-subject design: the EF−IF difference in each candidate indicator as path <em>a</em>, already registered as H3a/H3b, combined with its exploratory correlation with FPA target achievement rate as path <em>b</em>) will be computed for each of NASA-TLX and IMI-PC, with a bias-corrected bootstrap confidence interval, reported descriptively as a non-confirmatory, likely underpowered probe of the proposed pathways — <strong>not</strong> presented as an established mediation finding.</p><p><strong>Known confounds / how handled</strong>: Order effects (counterbalanced; checked as an underpowered-but-reported precondition, Section 3; <strong>all six primary comparisons additionally reported with and without order as a covariate, per Section 3, rather than relying on the precondition test as a binary gate</strong>). Practice/familiarity with AR/VR (excluded via exclusion criteria). Within-session carry-over between conditions (mitigated via 48–72h washout, see Section 3; acknowledged as not fully eliminable, see <code>Protocol_Master_Draft.md</code> Section 8 Limitations). <strong>EF/IF feedback complexity matching — resolved confounds vs. retained necessary differences (see <code>Protocol_Master_Draft.md</code> Section 4.1 for the full specification)</strong>:</p><p><em>Partially resolved confounds</em> (unintended asymmetries, not part of the theoretical manipulation; targeted by an explicit design change, but the design change itself has since been superseded by a further implementation revision — see &quot;Newly reintroduced asymmetries&quot; immediately below): the original EF display was static except for a brief 0.2s flash at foot contact, while the original IF display updated continuously every frame throughout the step — an asymmetry in sustained visual engagement independent of the intended attentional-focus manipulation. A first-pass fix made both conditions terminal (flash-on-foot-contact only) and unified their flash timing via one shared configuration constant (<code>FootOutDisplaySec</code>, currently 0.35s for both conditions — see <code>AR-FRONTEND.md</code>, &quot;Known issues&quot;: this value is hand-tuned, not derived from a fresh data-driven analysis the way an earlier 0.2s EF-only figure was). Both conditions also draw from one shared colour-blind-safe blue/orange palette (<code>FeedbackColors.cs</code>; see Section 4 exclusion criteria for the accompanying colour-vision screening item) and display an equal, word-count-matched <strong>3-second</strong> text reminder of the assigned attentional focus before each training block (corrected from an earlier-stated 5 seconds; <code>focusReminderDurationSec</code> in the current build is 3s — not during the block itself, to avoid introducing a new concurrent-vs-terminal asymmetry and to avoid a reading-while-walking safety hazard).</p><p><em>Newly reintroduced asymmetries (current build, per <code>IMUMoCap/docs/summry/AR-FRONTEND.md</code>, not yet resolved or fully disclosed prior to this revision)</em>: since that first-pass fix, EF and IF have diverged onto genuinely different rendering mechanisms rather than a single shared terminal-flash implementation, reopening two asymmetries of the same general kind the first-pass fix was meant to close:</p><ol><li><strong>Baseline-visibility duty cycle</strong>: the EF &quot;stone&quot; graphic (<code>stoneLeft</code>/<code>stoneRight</code>) is shown as soon as a training block starts and stays visible continuously for the whole block (it only ever pulses in scale/colour on a foot-contact event, via <code>PulseStone()</code>); the IF &quot;footprint&quot; graphic (<code>leftSolid</code>/<code>rightSolid</code>) is hidden by default for the entire block and becomes visible only for the ~0.35s flash window on each foot-contact event, via <code>FlashFoot()</code>. In effect, EF now has near-100% on-screen dwell time for its target icon across a block, while IF has near-0% dwell time outside its per-step flashes — the inverse configuration of the original static-EF/continuous-IF problem, not a symmetric fix of it. The previously-reported &quot;equalised proportion of step time during which the display is actively <em>changing</em>&quot; metric (flash duration ÷ average step duration) remains valid for describing the transient pulse/flash event itself, but no longer describes total visible exposure, because EF&#39;s target is visible at rest even when not pulsing and IF&#39;s is not.</li><li><strong>Feedback-valence coding asymmetry</strong>: EF&#39;s pulse uses only <code>FeedbackColors.OffTarget</code> (orange) on a missed step and leaves the stone at its own cached, unmodified texture colour when on-target — it never turns <code>OnTarget</code> (blue). IF&#39;s flash uses both <code>OnTarget</code> (blue, hit) and <code>OffTarget</code> (orange, miss) from the same shared palette. EF therefore only ever encodes a negative (&quot;you missed&quot;) signal, whereas IF encodes both positive and negative outcomes; this is a difference in feedback informativeness/valence structure independent of the external-vs-internal attentional-focus manipulation itself.</li></ol><p>Because both of these are display-implementation choices rather than deliberate instantiations of the EF/IF theoretical contrast (unlike the head-locked-anchoring and fixed-target-vs-measured-rotation differences addressed under &quot;Retained necessary differences&quot; below), they are treated here as <strong>acknowledged confounds</strong> rather than intended manipulation content, following the same disclosure standard applied to the display-anchoring finding in this section: a positive or null EF-vs-IF result on H2a–c/H3a–b cannot, on the current build, be fully separated from (1) unequal visual-target dwell time or (2) unequal availability of positive (on-target) feedback.</p><p><strong>Decision (recorded)</strong>: the authors selected <strong>Option (b)</strong> — a further AR-frontend revision was requested and completed — rather than Option (a) (accept the pre-revision build unchanged). The implementation described above (items 1-2) is the result of that revision and is confirmed as the <strong>final build used for data collection</strong>; it is not an interim state pending a further engineering choice. Choosing to revise the frontend did not eliminate either asymmetry (a frontend change that, for example, added an on-target colour state to the EF stone, or bounded its visible duration to match IF&#39;s flash window, was considered but not adopted); rather, the revision converged on this specific implementation and the authors elect to retain both asymmetries as disclosed limitations rather than re-engineer further, given that (i) ethics approval 008-11-2025 is already finalized for the underlying protocol, (ii) neither asymmetry requires a new participant-facing procedure to address it, and (iii) the directional-bias analysis immediately below is judged sufficient to make the resulting interpretive risk explicit and pre-specified rather than requiring elimination. <code>Protocol_Master_Draft.md</code> Section 4.1 as currently written still describes an earlier, pre-divergence, first-pass-fix design (identical solid-fill icon for both conditions, 5-second reminder, single &quot;feedback active time&quot; equality metric) and has not yet been re-synced to this confirmed build; per the Companion document freeze policy below, this re-sync is a required bookkeeping step before the freeze timestamp is set, not an open design decision.</p><p><strong>Directional-bias analysis (per hypothesis, added per Round 3 review Must-Fix #2)</strong>: because the confound-resolution decision above retains both asymmetries rather than eliminating them, their likely direction of influence on each primary hypothesis is pre-specified here so that results can be interpreted against a stated prior rather than post hoc:</p><ul><li><strong>H2a (EF &gt; IF target achievement rate)</strong>: the dwell-time asymmetry (EF&#39;s target continuously visible; IF&#39;s measured state visible only ~0.35s/step) plausibly <strong>inflates an EF advantage</strong> independent of attentional-focus content, since EF participants have a persistent visual reference to aim at for a much larger fraction of each step. A significant H2a result is therefore not cleanly attributable to attentional focus alone; a null or IF-favoring H2a result would be comparatively harder to explain away via this confound (it would hold despite a dwell-time advantage for EF).</li><li><strong>H2b (EF &lt; IF retention decrement) / H2c (condition × block interaction)</strong>: both asymmetries plausibly act during the training blocks (not the retention test, where feedback is removed for both conditions equally), so their direct influence on the retention-test outcome itself (H2b) is less direct than for H2a; however, if dwell-time or valence differences shape what is learned during training (e.g., differential reliance on the persistent EF target, per the guidance-hypothesis literature on continuous vs. faded feedback, Salmoni, Schmidt, &amp; Walter, 1984, <em>Psychological Bulletin</em>, DOI: 10.1037/0033-2909.95.3.355), this could plausibly produce a <strong>larger apparent EF retention decrement</strong> than attentional focus alone would predict (EF participants may be more dependent on the persistent visual target), which would work <strong>against</strong> H2b&#39;s predicted direction. H2c&#39;s within-session adaptation-trend comparison inherits both the H2a-direction (dwell-time) and H2b-direction (valence/dependency) risks across its three blocks.</li><li><strong>H3a (EF &lt; IF cognitive load) / H3b (EF &gt; IF perceived competence)</strong>: the feedback-valence asymmetry (EF: orange/&quot;missed&quot; signal only, never a positive on-target colour change; IF: both blue/&quot;hit&quot; and orange/&quot;missed&quot;) plausibly <strong>biases against both EF-favoring hypotheses</strong>. Under OPTIMAL theory&#39;s own enhanced-expectancies mechanism (Wulf &amp; Lewthwaite, 2016), receiving explicit positive feedback is itself expected to boost perceived competence; EF participants structurally never receive this signal while IF participants sometimes do, independent of attentional-focus content. This means a <strong>null H3b result is ambiguous between &quot;no true EF competence advantage&quot; and &quot;a design artifact suppressing it,&quot;</strong> while a <strong>significant H3b result (EF &gt; IF) would be a comparatively stronger finding</strong>, since it would hold despite a feedback-valence structure tilted toward IF. The same logic applies to H3a in the opposite subjective direction: the absence of positive confirmatory feedback is a plausible, independent contributor to subjectively higher workload/uncertainty for EF, so a null H3a result is similarly ambiguous, and a significant H3a result (EF &lt; IF cognitive load) would likewise be the stronger reading.</li><li><strong>Summary for interpretation</strong>: the two confounds are not expected to bias all six hypotheses in the same direction. Dwell-time asymmetry plausibly inflates an EF advantage on H2a (and, more speculatively, H2c); valence-coding asymmetry plausibly works against an EF advantage on H3a/H3b (and may contribute to an inflated H2b/H2c retention decrement for EF via feedback-dependency). A pattern of &quot;EF wins H2a but not H3a/H3b&quot; is therefore consistent with the confounds alone and does not by itself distinguish an attentional-focus effect from these implementation artifacts; this pattern-level caveat will be stated explicitly in the eventual manuscript&#39;s Discussion regardless of which hypotheses reach significance.</li></ul><p><em>Retained necessary differences</em> (not confounds — these differences are how the EF/IF manipulation itself is operationalised, and are deliberately not equalised): <strong>both EF and IF are rendered as head-locked, 3DoF HUD elements fixed in the wearer&#39;s field of view</strong> (per <code>Protocol_Master_Draft.md</code> Section 4.1&#39;s technical clarification: &quot;Ours is head-locked (3DoF): it moves with the head and is not anchored to the physical world&quot;) — the two conditions do <strong>not</strong> differ in display-anchoring mechanism, and the hardware does not support true world-locked/ground-anchored (SLAM) rendering for either condition. Correction to an earlier draft of this section, which incorrectly described EF&#39;s rendering as &quot;world-locked 3D... anchored to a real-world ground location&quot;: this was a drafting error, not a design feature; EF is properly described (per <code>Protocol_Master_Draft.md</code> Section 8&#39;s &quot;3DoF hardware constraint&quot;) as <strong>proximal EF</strong> — a head-locked display whose <em>content</em> is positioned to represent an external, environment-anchored target location (~1.5 m ahead, ground level), rather than a display that is itself world-anchored. What is retained and deliberately not equalised is therefore the <strong>represented content/referent</strong> of each display, not its anchoring mechanism: EF&#39;s content represents an external ground-target location, consistent with EF&#39;s theoretical definition of attention directed at an external, environment-anchored effect; IF&#39;s content represents an abstracted state of the participant&#39;s own foot/body, consistent with IF&#39;s theoretical definition of attention directed at the body movement itself. Because both displays share an identical head-locked rendering mechanism, the specific rival-explanation risk of a <em>display-anchoring-format</em> confound (differential depth-cue processing, gaze/head-coordination demand, or vestibular-ocular/postural load arising from one display being world-anchored and the other head-anchored) does <strong>not</strong> apply here. A narrower, already-acknowledged limitation remains, however: because EF is only a <em>proximal</em> approximation of a true world-locked external target (a hardware constraint, not a chosen equalisation), a positive EF &gt; IF finding cannot be fully attributed to attentional-focus content alone independent of this proximal-EF approximation; this is the same limitation already flagged under &quot;3DoF hardware constraint&quot; in <code>Protocol_Master_Draft.md</code> Section 8, restated here so Section 6 and Section 7 are mutually consistent rather than describing two apparently different confounds.</p><p>This is also where the current build&#39;s remaining EF/IF content differences belong, now that the icon-shape claim above has been corrected: EF renders as a distinct &quot;stepping stone&quot; sprite that is set once per block to a fixed target angle/position and never rotates to show the participant&#39;s actual measured angle; IF renders as a &quot;footprint&quot; sprite that is hidden until a foot-contact event, then briefly rotates to the participant&#39;s actual measured error (<code>msg.errorL</code>/<code>msg.errorR</code> = FPA − target) before hiding again. This fixed-target-only-vs-measured-rotation distinction is judged a <strong>retained, theoretically-motivated difference</strong> (EF communicates only the external goal location, consistent with attention-on-effect; IF communicates the participant&#39;s own measured body state, consistent with attention-on-movement) and is listed here for completeness rather than under &quot;Newly reintroduced asymmetries&quot; above, which is reserved for differences not motivated by the EF/IF theoretical contrast itself.</p><p><em>Not yet independently verified</em>: whether the blue and orange hues chosen are subjectively matched in visual salience/contrast against the AR display background (colour-blind-safety and salience-matching are related but distinct properties); this will be checked informally during the next pilot round rather than assumed from palette selection alone.</p><hr><h2 id="_7-other" tabindex="-1"><a class="header-anchor" href="#_7-other" aria-hidden="true">#</a> 7. Other</h2><p><strong>Data availability</strong>: De-identified processed data (FPA-derived outcome variables, questionnaire scores) and analysis code will be made publicly available via the OSF project associated with this registration upon manuscript acceptance. Raw IMU time-series data (large file volume) will be archived on Zenodo with a persistent DOI, linked from the OSF project. Data will be de-identified prior to deposit; no directly identifying information (name, contact details, raw video) will be shared. Access to any residual identifiable material (e.g., session video used only for internal QA) is available upon reasonable request to the corresponding author, subject to institutional ethics approval (008-11-2025) data-sharing terms.</p><p><strong>Ethics</strong>: Ethics approval <strong>008-11-2025</strong> obtained for the finalized protocol (including the pilot-based safety monitoring replacing formal SSQ/ARSQ); confirmed by researcher as finalized, no further protocol changes anticipated (see <code>Protocol_Master_Draft.md</code> Section 9(b)).</p><p><strong>Acknowledged limitations</strong>: See <code>Protocol_Master_Draft.md</code> Section 8 for the full list (no independent no-feedback control group; 3DoF/proximal-EF hardware constraint — both EF and IF are head-locked HUD renderings, so this limitation concerns EF&#39;s content being only a proximal approximation of a true world-anchored external target, not a display-anchoring-mechanism difference between conditions, see Section 6 above; two-visit design washout cannot fully eliminate carry-over; exploratory sample size N&lt;20 underpowered for small effects; healthy-participant sample may not generalize to clinical populations). <strong>Additionally, in the confirmed final AR frontend build used for data collection</strong> (see Section 6, &quot;Newly reintroduced asymmetries&quot; and &quot;Decision (recorded)&quot;): EF&#39;s target icon is continuously visible for the whole training block while IF&#39;s icon is visible only during its brief (~0.35s) per-step flash (an unequal visual-target dwell-time confound), and EF&#39;s feedback pulse encodes only missed-target (orange) outcomes while IF&#39;s flash encodes both on-target (blue) and missed-target (orange) outcomes (an unequal feedback-valence confound). The authors selected Option (b) (requested and completed a further frontend revision) rather than leaving these open, but elected to retain both asymmetries in the resulting final build as disclosed, accepted limitations rather than eliminate them; they are distinct from the already-disclosed 3DoF/proximal-EF and head-locked-anchoring limitations above. Per Section 6&#39;s directional-bias analysis, these are not expected to bias all six hypotheses in the same direction: dwell-time asymmetry plausibly inflates an EF advantage on H2a (and possibly H2c), while valence-coding asymmetry plausibly works against an EF advantage on H3a/H3b (and may inflate an EF retention decrement on H2b/H2c via feedback-dependency); a positive or null EF-vs-IF finding on H2a–c/H3a–b cannot, on this build, be fully attributed to attentional focus alone independent of these two implementation asymmetries, and the pattern described above (not a uniform bias) will be stated explicitly in the eventual manuscript&#39;s Discussion.</p><p><strong>Deviations from this pre-registration</strong>: Any deviation from the analysis plan above, discovered necessary after data collection begins, will be explicitly reported and justified in the manuscript as a post-hoc/exploratory departure from the pre-registered plan, not presented as originally planned.</p>',27);function u(m,g){const o=a("ExternalLinkIcon");return r(),s("div",null,[c,t("p",null,[t("strong",null,[e("Removed variables (formerly planned, now excluded — see "),t("a",h,[e("CHANGELOG.md"),d(o)]),e(" for full history)")]),e(": Custom QoE Questionnaire (4 dimensions), SAM (Valence/Arousal/Dominance), SSQ/ARSQ formal discomfort questionnaire (replaced by verbal screening).")]),p])}const b=n(l,[["render",u],["__file","Preregistration_Draft.html.vue"]]);export{b as default};
